import{_ as l,o as e,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-04-03 :: Ceph Testing meeting","description":"","frontmatter":{"title":"2019-04-03 :: Ceph Testing meeting","date":"2019-04-03T00:00:00.000Z","updated":"2019-04-10T00:00:00.000Z","tags":["Ceph","分布式存储","代码审查","测试环境","Python版本支持"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-03_-_-_Ceph_Testing_meeting.md","filePath":"posts/2019/2019-04-03_-_-_Ceph_Testing_meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-04-03_-_-_Ceph_Testing_meeting.md"};function s(r,t,g,_,p,a){return e(),i("div",null,[...t[0]||(t[0]=[o("<p>会议纪要：</p><p><strong>会议时间</strong>： 未知 <strong>参会人员</strong>： Gregory、Rick、Zach、Yuri等 <strong>会议主题</strong>： Ceph分布式存储项目进展、代码审查流程、测试环境搭建、Python版本支持等</p><p><strong>会议内容</strong>：</p><ol><li><strong>Gregory出席情况</strong>： 今日会议未提及Gregory的出席情况。</li><li><strong>代码审查流程</strong>： <ul><li>代码审查流程耗时过长，从请求到反馈需要数周时间。</li><li>GitHub支持请求代码审查的功能，但参与者响应缓慢。</li><li>建议提高代码审查的积极性，建立定期会议和测试周，鼓励参与者积极参与。</li></ul></li><li><strong>测试环境搭建</strong>： <ul><li>目前缺乏统一的测试环境，需运行不同API的测试。</li><li>已有测试套件支持Ubuntu，但CentOS版本存在问题。</li><li>需要改进内部工具，实现自动上传镜像和运行测试。</li></ul></li><li><strong>Python版本支持</strong>： <ul><li>讨论了Ceph项目对Python 3的支持，需明确支持的版本。</li><li>需要增加代码检查器，确保代码兼容性。</li></ul></li><li><strong>行动计划</strong>： <ul><li>加大会议参与度，提高代码审查效率。</li><li>完善测试环境，确保不同API的测试运行。</li><li>明确Python版本支持，并增加代码检查器。</li></ul></li></ol><p><strong>后续行动</strong>：</p><ul><li>确认Gregory的出席情况。</li><li>推动代码审查流程的改进。</li><li>搭建统一的测试环境。</li><li>明确Python版本支持，并增加代码检查器。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提及了Ceph项目的一些关键词，如：CPM、look into tautology、cold rooks、cube spray、PR、pull request、CI、PR测试、Python版本支持等。</li></ul>",8)])])}const c=l(n,[["render",s]]);export{h as __pageData,c as default};
